fn zip[T, U](a: &Vec[T], b: &Vec[U]) -> Vec[(T, U)]
  requires: a.len() == b.len();
{
  var result = Vec[(T, U)]();
  for i in 0..a.len() {
    result.push((a[i], b[i]));
  }
  return result;
}

fn main() -> Int {
  let nums = Vec[Int](); nums.push(1); nums.push(2); nums.push(3);
  let strs = Vec[Str](); strs.push("a"); strs.push("b"); strs.push("c");
  let zipped = zip[Int, Str](&nums, &strs);
  return zipped.len();
}
